tariff "t"
let w = shipment.weight ?? 0 lb
let rate = tables.Breaks[w] ?? fail "No break"
charge "Linehaul" = rate * w
test "inside a band" {
  given shipment.weight = 600 lb
  given tables.Breaks[0 lb] = $40/cwt
  given tables.Breaks[500 lb] = $30/cwt
  given tables.Breaks[1_000 lb] = $20/cwt
  expect total == $180
}
test "the top band is open-ended" {
  given shipment.weight = 5_000 lb
  given tables.Breaks[0 lb] = $40/cwt
  given tables.Breaks[10 cwt] = $20/cwt
  expect total == $1_000
}
test "only the given cells" {
  given shipment.weight = 600 lb
  given tables.Breaks[1_000 lb] = $20/cwt
  expect fails "No break"
}
test "a later given replaces an earlier" {
  given shipment.weight = 600 lb
  given tables.Breaks[0 lb] = $40/cwt
  given tables.Breaks[0 lb] = $10/cwt
  expect total == $60
}
test "no given cells reads the live table" {
  given shipment.weight = 600 lb
  expect total == $594
}

tariff "t"
let rate = tables.Zones[lane.origin.zip3, lane.destination.zip3] ?? fail "No zone"
charge "Linehaul" = rate * 1 cwt
test "a given cell" {
  given lane.origin.zip3 = "752"
  given lane.destination.zip3 = "606"
  given tables.Zones[" 752 ", "606"] = $20/cwt
  expect total == $20
}
test "a miss among given cells is none" {
  given lane.origin.zip3 = "752"
  given lane.destination.zip3 = "999"
  given tables.Zones["752", "606"] = $20/cwt
  expect fails "No zone"
}
test "without cells it needs the live table" {
  given lane.origin.zip3 = "752"
  given lane.destination.zip3 = "606"
  expect total == $20
}

